/* Base64-encoded brand images for the notification email template
   (functions/email.ts) — baked in as plain module data rather than read
   from disk at runtime, so there are no serverless-bundle asset-tracing
   concerns. Sourced from the club shared Drive (see the old Apps Script
   bulk-email tool) — re-fetch and regenerate this file if the source
   images in Drive ever change. */

export interface EmailImage {
  cid: string;
  filename: string;
  contentType: string;
  base64: string;
}

export const EMAIL_IMAGES: EmailImage[] = [
  { cid: 'engsocLogo', filename: 'engsoc-logo.png', contentType: 'image/png', base64: '' },
  { cid: 'facebookLogo', filename: 'facebook-logo.png', contentType: 'image/png', base64: '' },
  { cid: 'instagramLogo', filename: 'instagram-logo.png', contentType: 'image/png', base64: '' },
  { cid: 'linkedInLogo', filename: 'linkedin-logo.png', contentType: 'image/png', base64: '' },
  { cid: 'youtubeLogo', filename: 'youtube-logo.png', contentType: 'image/png', base64: '' },
];
